def add_img(img_fname, caption="", width_in=5.2):
    img_path = os.path.join(STEPS_DIR, img_fname)
    if not os.path.exists(img_path):
        img_path = os.path.join(BASE_DIR, "screenshots", img_fname)
    if not os.path.exists(img_path):
        img_path = os.path.join(WORKFLOW_DIR, img_fname)
    
    if os.path.exists(img_path):
        p_img = doc.add_paragraph()
        p_img.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p_img.paragraph_format.space_before = Pt(6)
        p_img.paragraph_format.space_after = Pt(2)
        run_img = p_img.add_run()
        run_img.add_picture(img_path, width=Inches(width_in))
        if caption:
            p_cap = doc.add_paragraph()
            p_cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
            run_cap = p_cap.add_run(caption)
            format_run_xml(run_cap, size_pt=14, italic=True)
            p_cap.paragraph_format.space_after = Pt(8)
    else:
        print(f"Warning: image not found: {img_fname}")

def set_cell(cell, text, bold=False, align=WD_ALIGN_PARAGRAPH.LEFT, size_pt=14):
    cell.text = ""
    p = cell.paragraphs[0]
    p.alignment = align
    p.paragraph_format.space_before = Pt(2)
    p.paragraph_format.space_after = Pt(2)
    run = p.add_run(text)
    format_run_xml(run, size_pt=size_pt, bold=bold)

