# =============================================================================
# PART 3: CONVERT TO PDF VIA WORD COM
# =============================================================================
subprocess.run(["powershell", "-Command", "Stop-Process -Name WINWORD -Force -ErrorAction SilentlyContinue"], capture_output=True)

import win32com.client
print("Launching Microsoft Word COM for PDF conversion...")
word = win32com.client.DispatchEx("Word.Application")
word.Visible = False
word.DisplayAlerts = 0

try:
    pdf_path = os.path.splitext(docx_path)[0] + ".pdf"
    print(f"Converting: {os.path.basename(docx_path)} -> {os.path.basename(pdf_path)}")
    d = word.Documents.Open(docx_path, ReadOnly=True, Visible=False)
    d.SaveAs2(pdf_path, FileFormat=17) # wdFormatPDF
    d.Close(SaveChanges=0)
    size_mb = os.path.getsize(pdf_path) / (1024 * 1024)
    print(f"  Successfully converted to PDF: {size_mb:.2f} MB")
finally:
    word.Quit()
    print("Word COM closed successfully.")

